("m2.lastScan.detail", "Finished {0}.", "انتهى في {0}."),
("m2.check.history", "Defender detections in the last 30 days", "اكتشافات Defender خلال آخر 30 يوماً"),
("m2.history.detail", "{0} detections recorded by Defender.", "{0} اكتشافات سجّلها Defender."),
("m2.detection.active.title", "Defender detected {0} and it is not resolved", "اكتشف Defender {0} ولم تتم معالجته"),
("m2.detection.active.why", "Defender's own record says this threat was found and the action against it did not complete.", "سجل Defender نفسه يقول إن هذا التهديد اكتُشف وإن الإجراء ضده لم يكتمل."),
("m2.detection.active.action", "Open Windows Security > Virus & threat protection > Protection history and choose an action, then run a full scan.", "افتح أمن ويندوز > الحماية من الفيروسات والمخاطر > محفوظات الحماية واختر إجراءً، ثم شغّل فحصاً كاملاً."),
("m2.detection.handled.title", "Defender detected and handled {0}", "اكتشف Defender {0} وعالجه"),
("m2.detection.handled.why", "Defender quarantined or removed it. It is listed so you know it happened.", "وضعه Defender في الحجر أو أزاله. يُعرض لتعرف أن ذلك حدث."),
("m2.detection.handled.action", "No action needed unless you believe it was a false positive; then check the quarantine on the Protection page.", "لا حاجة لإجراء ما لم تعتقد أنه اكتشاف خاطئ؛ عندها راجع الحجر في صفحة الحماية."),
("m2.check.pua", "Blocking of potentially unwanted apps (PUA)", "حظر التطبيقات غير المرغوب فيها (PUA)"),
("m2.pua.on", "On.", "مفعّل."),
("m2.pua.audit", "Audit only: detected but not blocked.", "تدقيق فقط: يُكتشف ولا يُحظر."),
("m2.pua.off", "Off.", "متوقف."),
("m2.pua.title", "Defender does not block potentially unwanted apps", "لا يحظر Defender التطبيقات غير المرغوب فيها"),
("m2.pua.why", "Bundled adware, browser hijackers and fake \"PC optimizers\" are often not malware, so Defender lets them in unless PUA blocking is on.", "برامج الإعلانات المرفقة وخاطفات المتصفح و\"محسّنات الحاسوب\" المزيفة ليست برمجيات خبيثة غالباً، لذا يسمح بها Defender ما لم يكن حظر PUA مفعّلاً."),
("m2.pua.action", "Turn PUA blocking on. PC Doctor can do it for you, with undo.", "فعّل حظر PUA. يستطيع طبيب الحاسوب فعل ذلك مع إمكانية التراجع."),
("m2.pua.undo", "The policy value is recorded in the change journal and can be removed from the Changes tab.", "تُسجَّل قيمة السياسة في سجل التغييرات ويمكن إزالتها من تبويب التغييرات."),
("m2.check.scan", "Malware scan", "فحص البرمجيات الخبيثة"),
("m2.scan.onDemand", "Not part of the Health Check: start a Defender scan from the Protection page.", "ليس جزءاً من فحص الصحة: ابدأ فحص Defender من صفحة الحماية."),
("fix.pua.title", "Block potentially unwanted apps", "حظر التطبيقات غير المرغوب فيها"),
("fix.pua.explain", "Sets the documented Group Policy value that turns on Defender's PUA blocking.", "يضبط قيمة سياسة المجموعة الموثّقة التي تفعّل حظر PUA في Defender."),
# ---- Protection page
("protection.engine.checking", "Checking which antivirus is active…", "جارٍ التحقق من برنامج مكافحة الفيروسات النشط…"),
("protection.scan.title", "Scan with Microsoft Defender", "افحص باستخدام Microsoft Defender"),
("protection.scan.body", "Defender updates its signatures first. A quick scan takes minutes; a full scan can take hours and the PC stays usable. Defender quarantines what it finds, as it normally does; nothing is deleted.", "يحدّث Defender تواقيعه أولاً. الفحص السريع يستغرق دقائق؛ أما الكامل فقد يستغرق ساعات ويبقى الجهاز قابلاً للاستخدام. يضع Defender ما يجده في الحجر كعادته؛ لا يُحذف شيء."),
