("protection.result.handled", "Defender found {0} threats and handled them", "وجد Defender {0} تهديدات وعالجها"),
("protection.result.remaining", "Defender found {0} threats that still need action", "وجد Defender {0} تهديدات ما زالت تحتاج إجراءً"),
("protection.result.failed", "The scan did not complete, so there is no result", "لم يكتمل الفحص، لذا لا توجد نتيجة"),
